<?php
namespace App\Controllers\Admin;use App\Core\Controller;use App\Helpers\AdminAuth;
class Categories extends Controller {
 public function index():void{$this->handleCors();$this->admin();$rows=$this->db()->query('SELECT c.*,(SELECT COUNT(*) FROM vp_products p WHERE p.category_id=c.id) product_count FROM vp_categories c ORDER BY c.sort_order,c.name')->result_array()?:[];foreach($rows as &$r){$r['id']=(int)$r['id'];$r['sort_order']=(int)$r['sort_order'];$r['is_featured']=(int)$r['is_featured'];$r['product_count']=(int)$r['product_count'];}$this->success(['items'=>$rows],'Categories loaded');}
 public function save($id=null):void{$this->handleCors();if(!$this->isPost())$this->error('Method not allowed',405);$this->admin();$b=$this->getBody();$id=(int)$id;$name=trim((string)($b['name']??''));if($name==='')$this->error('Nama kategori wajib diisi',422);$slug=trim((string)($b['slug']??''));if($slug==='')$slug=strtolower(trim(preg_replace('/[^a-z0-9]+/i','-',$name),'-'));if($slug==='')$slug='kategori';$status=(string)($b['status']??'published');if(!in_array($status,['draft','published','archived'],true))$status='published';$dup=$this->db()->query('SELECT id FROM vp_categories WHERE slug=? AND id<>? LIMIT 1',[$slug,$id])->row_array();if($dup)$this->error('Slug sudah dipakai kategori lain',422);$now=$GLOBALS['now']??date('Y-m-d H:i:s');$data=['name'=>$name,'slug'=>$slug,'description'=>trim((string)($b['description']??''))?:null,'image_url'=>trim((string)($b['image_url']??''))?:null,'sort_order'=>(int)($b['sort_order']??0),'is_featured'=>!empty($b['is_featured'])?1:0,'status'=>$status,'updated_at'=>$now];if($id>0){$ex=$this->db()->query('SELECT id FROM vp_categories WHERE id=? LIMIT 1',[$id])->row_array();if(!$ex)$this->error('Kategori tidak ditemukan',404);$this->db()->update('vp_categories',$data,['id'=>$id]);}else{$data['created_at']=$now;$id=(int)$this->db()->insert('vp_categories',$data);}$row=$this->db()->query('SELECT * FROM vp_categories WHERE id=? LIMIT 1',[$id])->row_array();$this->success(['id'=>(int)$row['id'],'name'=>$row['name'],'slug'=>$row['slug'],'description'=>$row['description'],'image_url'=>$row['image_url'],'sort_order'=>(int)$row['sort_order'],'is_featured'=>(int)$row['is_featured'],'status'=>$row['status']],'Kategori disimpan');}
 public function remove($id=null):void{$this->handleCors();if(!$this->isPost())$this->error('Method not allowed',405);$this->admin();$id=(int)$id;$count=(int)($this->db()->query('SELECT COUNT(*) c FROM vp_products WHERE category_id=?',[$id])->row_array()['c']??0);if($count>0)$this->error('Kategori masih dipakai '.$count.' produk. Pindahkan produk terlebih dahulu.',422);$this->db()->delete('vp_categories',['id'=>$id]);$this->success(null,'Kategori dihapus');}
 private function admin():array{$a=AdminAuth::user();if(!$a)$this->error('Unauthorized',401);return $a;}
}
